singe_loader::functions! { crate::LIBRARY;
    /// Returns the IFD offset of the image (IFD) following `ifd_offset` in the chain.
    ///
    /// Reads each IFD's header (entry count and next-IFD pointer) and extends the internal chain map as needed; it does not parse tag data.
    ///
    /// **Count images** - walk and tally:
    ///
    ///
    ///
    /// ```text
    ///  nvtiffStreamHeader_t h; uint32_t n = 0;
    ///  nvtiffStreamGetHeader(s, &h);
    ///  for (size_t off = h.first_ifd_offset; off != NVTIFF_NO_IMAGE; n++)
    ///      nvtiffStreamGetNextIFDOffset(s, off, &off);
    /// ```
    ///
    /// **Collect offsets** - push each into a container:
    ///
    ///
    ///
    /// ```text
    ///  nvtiffStreamHeader_t h;
    ///  nvtiffStreamGetHeader(s, &h);
    ///  std::vector&lt;size_t> offsets;
    ///  for (size_t off = h.first_ifd_offset; off != NVTIFF_NO_IMAGE; )
    ///      { offsets.push_back(off); nvtiffStreamGetNextIFDOffset(s, off, &off); }
    /// ```
    ///
    /// To walk a SubIFD chain, seed with the SubIFD's offset instead of `h.first_ifd_offset`.
    ///
    ///
    ///
    /// # Return value
    ///
    /// An error code as specified in `nvtiffStatus_t` "API Return Status Codes".
    ///
    /// # Parameters
    ///
    /// - `tiff_stream`: \[in\] TIFF stream handle.
    /// - `ifd_offset`: \[in\] Current image's offset; 0 selects the first IFD.
    /// - `next_ifd_offset`: \[out\] Offset of the following image, or `NVTIFF_NO_IMAGE` at the end of the chain.
    pub fn nvtiffStreamGetNextIFDOffset(
        tiff_stream: nvtiffStream_t,
        ifd_offset: size_t,
        next_ifd_offset: *mut size_t,
    ) -> nvtiffStatus_t;
}
