singe_loader::functions! { crate::LIBRARY;
    /// Sets the decode output format.
    ///
    /// The default value is [`nvtiffOutputFormat_t::NVTIFF_OUTPUT_UNCHANGED_I`].
    ///
    /// **Buffer size and pitch requirements:**
    ///
    /// When [`nvtiffOutputFormat_t::NVTIFF_OUTPUT_UNCHANGED_I`] is used:
    ///
    /// * Buffer size: `image_height * DivUp(image_width * bits_per_pixel, 8)`
    /// * Pitch must be aligned to `DivUp(bits_per_sample\[0\], 8)` bytes.
    /// * Default pitch (if not specified): `DivUp(image_width * bits_per_pixel, 8)`
    ///
    /// When [`nvtiffOutputFormat_t::NVTIFF_OUTPUT_RGB_I_UINT8`] is used:
    ///
    /// * Buffer size: `image_width * image_height * 3`
    /// * Pitch must be aligned to 1 byte.
    ///
    /// When [`nvtiffOutputFormat_t::NVTIFF_OUTPUT_RGB_I_UINT16`] is used:
    ///
    /// * Buffer size: `image_width * image_height * 6`
    /// * Pitch must be aligned to 2 bytes.
    ///
    /// # Parameters
    ///
    /// - `decode_params`: Decode parameters handle.
    /// - `format`: Output format value.
    pub fn nvtiffDecodeParamsSetOutputFormat(
        decode_params: nvtiffDecodeParams_t,
        format: nvtiffOutputFormat_t,
    ) -> nvtiffStatus_t;
}
singe_loader::functions! { crate::LIBRARY;
    /// Configures the explicit set of regions to decode.
    ///
    /// Replaces the entire explicit region set in `decode_params` with exactly the provided array. This is the only region-configuration API; a full image at any IFD offset is a one-element array with `width` = `height` = 0.
    ///
    /// Fresh params already represent the default request (one full image at IFD offset 0), so the common "decode the first full image" path needs no call to this function. Passing `regions` = `NULL` and `count` = 0 resets params to that default; this is supported for state reset, but prefer fresh params for the default path and an explicit one-element array for a non-default full-image decode.
    ///
    /// The region descriptors are source-free: they carry no stream handle, and their IFD offsets are interpreted against whichever `tiff_stream` is later passed to [`nvtiffDecode`] or [`nvtiffDecodeCheckSupported`]. A configured params object can therefore be reused across streams.
    ///
    /// This call performs only mechanical argument checks; it does not validate region contents against any stream. IFD offset validity, ROI bounds, codec support, output descriptors, and batch compatibility are validated by [`nvtiffDecodeCheckSupported`] and [`nvtiffDecode`].
    ///
    /// For a non-empty input, the caller's array is deep-copied before this call returns, so the caller may free or mutate it afterwards. If the call fails a mechanical check or an allocation while copying, the existing params state is left unchanged.
    ///
    ///
    ///
    /// # Return value
    ///
    /// An error code as specified in `nvtiffStatus_t` "API Return Status Codes".
    ///
    /// # Parameters
    ///
    /// - `decode_params`: \[in/out\] Decode parameters handle.
    /// - `regions`: \[in\] Array of `count` region descriptors, or `NULL` when `count` is 0.
    /// - `count`: \[in\] Number of regions, or 0 to reset to the default first full-image request.
    pub fn nvtiffDecodeParamsSetRegions(
        decode_params: nvtiffDecodeParams_t,
        regions: *const nvtiffDecodeRegion_t,
        count: u32,
    ) -> nvtiffStatus_t;
}
